        align = format[1]
        format = format[2:]

    if format.startswith(('+', '-', ' ')):
        format = format[1:]

    zero = False
    if format and format[0] == '0':
        zero = True
        format = format[1:]

    width = ''
    while format:
        if not format[0].isdigit():
