    text: t.Any,
    pattern: t.Any,
    repl: t.Union[str, t.Callable[[re.Match[str]], str]],
    ignore_case: bool = False,
    count: int = 0,
    escape: bool = True,
    from_start: bool = False,
    from_end: bool = False,
) -> str:
    text = pyd.to_string(text)

    if pattern is None:
        return text

    if not pyd.is_function(repl):
        repl = pyd.to_string(repl)

    flags = re.IGNORECASE if ignore_case else 0

    if isinstance(pattern, typing.Pattern):
        pat = pattern
    else:
        pattern = pyd.to_string(pattern)

        if escape:
            pattern = re.escape(pattern)

        pat = re.compile(pattern, flags=flags)

    if from_start or from_end:
        pattern = pat.pattern
        # The compiled flags retain leading global flag groups. Remove those
        # groups before embedding the expression, including verbose trivia.
        prefix = r"\(\?[aiLmsux]+\)|\(\?#(?:\\.|[^\\)])*\)"
