            prefix += r"|[ \t\n\r\f\v]+|#[^\n]*(?:\n|$)"
        pattern = re.sub(f"^(?:{prefix})+", "", pattern)
        if pat.flags & re.VERBOSE:
            pattern += "\n"
        pattern = f"(?:{pattern})"
        if from_start:
            pattern = r"\A" + pattern
        if from_end:
            pattern += r"\Z"
        pat = re.compile(pattern, flags=pat.flags)

    return pat.sub(repl, text, count=count)

